"""Map workspace built from the assignment's unmodified delivery coordinates."""
import json
from pathlib import Path

def map_html(data, icons, failure):
    root=Path(__file__).resolve().parent
    config=json.loads((root/'assets/map-config.json').read_text())
    filters=''.join(
        f'''<button data-filter="{status}" :class="{{selected:filter === '{status}'}}" :aria-pressed="filter === '{status}'" :aria-label="'{label} '+count('{status}')" @click="setFilter('{status}')"><span class="filter-symbol {status}" aria-hidden="true">{icons['check'] if status=='completed' else icons['warning'] if status=='failed' else ''}</span><span class="filter-word">{label}</span><span class="filter-count" x-text="count('{status}')">{len(data) if status=='all' else sum(s['status']==status for s in data)}</span></button>'''
        for status,label in [('all','All'),('pending','Pending'),('completed','Completed'),('failed','Failed')]
    )
    template='''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="referrer" content="strict-origin-when-cross-origin"><title>ocean delivery · Delivery map</title><link rel="icon" type="image/png" href="assets/app-icon-32.png?v=first"><link rel="apple-touch-icon" href="assets/app-icon-180.png?v=first"><link rel="stylesheet" href="vendor/leaflet/leaflet.css"><link rel="stylesheet" href="vendor/leaflet/MarkerCluster.css"><link rel="stylesheet" href="assets/app.css"><link rel="stylesheet" href="assets/refined.css"><link rel="stylesheet" href="assets/map.css"><script>window.DELIVERIES=__DATA__;window.MAP_CONFIG=__CONFIG__;window.MAP_ICONS=__ICONS__;</script><script src="vendor/leaflet/leaflet.js"></script><script src="vendor/leaflet/markercluster.js"></script><script src="assets/map.js"></script><script src="assets/app.js"></script><script defer src="vendor/alpine.min.js"></script></head>
<body data-variant="a" data-map="true"><main class="phone map-phone" x-data="deliveryApp" :data-panel="detailOpen?'detail':listOpen?'list':'map'" @keydown.escape.window="escape()">
<div id="delivery-map" x-ref="mapCanvas" class="delivery-map" aria-label="Sydney delivery map with status markers" role="region"></div>
<div class="map-top-shade" aria-hidden="true"></div>
<div class="system-bar" aria-hidden="true"><span>9:41</span><span class="system-icons">__signal____battery__</span></div>
<header class="app-top map-top"><div><h1>ocean delivery</h1><p>Sydney <span aria-hidden="true">·</span> <span x-text="stops.length">30</span> stops</p></div><div class="top-tools"><button class="icon-button search-trigger" @click="openSearch()" aria-label="Search stops">__search__</button><button class="connection main-toggle" :class="{offline:!online}" role="switch" :aria-checked="online" aria-label="Online connection" @click="toggleOnline()"><span class="connection-dot"></span><span x-text="online?'Online':'Offline'">Online</span><span class="switch" :class="{on:online}"></span></button></div></header>
<div class="map-filters" role="group" aria-label="Filter map stops by status">__FILTERS__</div>
<div class="search map-search" x-cloak x-show="searchOpen" :style="searchOpen?'':'pointer-events:none'" x-transition.opacity.duration.150ms>__search__<input x-ref="searchInput" type="search" x-model="search" placeholder="Customer, address or reference" aria-label="Find a customer or reference"><button @click="closeSearch()" aria-label="Close search">__close__</button></div>
<div class="map-empty" role="status" x-cloak x-show="visibleCount===0 && !searchOpen">No matching stops. Try another filter.</div>
<div class="map-error" role="status" x-cloak x-show="mapFailed"><span>Map background unavailable. Your stops are still here.</span><button @click="retryMap()" aria-label="Retry map background">__sync__</button></div>
<div class="map-controls" aria-label="Map controls"><button class="map-control" @click="zoomMap(1)" aria-label="Zoom in"><span aria-hidden="true">+</span></button><button class="map-control" @click="zoomMap(-1)" aria-label="Zoom out"><span aria-hidden="true">−</span></button><span class="control-divider"></span><button class="map-control" @click="fitMap()" aria-label="Show all matching stops">__mapFit__</button><button class="map-control locate-control" @click="locateDriver()" aria-label="Show my location">__locate__</button><span class="control-divider"></span><button class="map-control map-sync-control" :class="{waiting:queue.length,rotating:syncing}" @click="syncUpdates()" :aria-label="'Sync updates'+(syncing?' · syncing':queue.length?' · '+queue.length+' waiting':'')" :aria-busy="syncing">__sync__<span class="tool-queue-count" x-cloak x-show="queue.length" x-text="queue.length"></span></button></div>
<section class="map-overview" x-ref="runOverview" x-show="!detailOpen && !listOpen && page==='stops'" x-transition.opacity.duration.180ms aria-label="Delivery run summary"><div class="map-overview-top"><div><h2><strong x-text="count('pending')">24</strong> left to deliver</h2><p><span x-text="count('completed')+count('failed')">6</span> of <span x-text="stops.length">30</span> finished</p></div><button class="overview-list" @click="openList()" aria-label="Browse stops">__list__<span>Browse stops</span>__arrow__</button></div><div class="map-run-progress" aria-hidden="true"><span class="completed" :style="'width:'+count('completed')/stops.length*100+'%'"></span><span class="failed" :style="'width:'+count('failed')/stops.length*100+'%'"></span></div><template x-if="nearestStop"><button class="overview-nearest" @click="openStop(nearestStop.reference)" :aria-label="'Open nearest stop, '+nearestStop.customer_name+', '+distanceLabel(nearestStop)" title="Straight-line distance from your location"><span class="nearest-symbol list-status-symbol" :class="nearestStop.status"><span x-show="nearestStop.status==='pending'" class="pending-ring" aria-hidden="true"></span><span x-show="nearestStop.status==='completed'">__check__</span><span x-show="nearestStop.status==='failed'">__warning__</span></span><span class="nearest-identity"><span class="nearest-caption" x-text="filter==='all'&&!search?'Nearest stop':'Nearest matching stop'">Nearest stop</span><strong x-text="nearestStop.customer_name">Silverline Supplies</strong></span><span class="nearest-distance" x-text="distanceLabel(nearestStop)">2.4 km</span>__arrow__</button></template><div class="overview-local"><span class="driver-legend"><i></i>Your location</span><span x-text="online?(queue.length?queue.length+' waiting to sync':'Updates synced'):'Offline · saved on device'"></span></div></section>
<section class="map-drawer stop-browser" x-ref="stopListPanel" x-cloak x-show="listOpen && !detailOpen && page==='stops'" x-transition:enter="sheet-enter" x-transition:enter-start="sheet-start" x-transition:enter-end="sheet-end" x-transition:leave="sheet-leave" x-transition:leave-start="sheet-end" x-transition:leave-end="sheet-start" aria-label="Stop list"><div class="sheet-grip"></div><header class="drawer-head"><div><h2>Stops on the map</h2><p x-text="visibleCount+' stop'+(visibleCount===1?'':'s')+' · Nearest first'">30 matching stops</p></div><button class="icon-button" x-ref="stopListClose" @click="listOpen=false" aria-label="Close stop list">__close__</button></header><div class="drawer-scroll" x-ref="stopListScroll"><template x-for="stop in filteredStops" :key="stop.reference"><button class="map-list-row" :id="'stop-'+stop.reference" :data-ref="stop.reference" @click="openStop(stop.reference,'list')" :aria-label="'Open '+stop.customer_name+', '+stop.reference"><span class="list-status-symbol" :class="stop.status"><span x-show="stop.status==='pending'" class="pending-ring" aria-hidden="true"></span><span x-show="stop.status==='completed'">__check__</span><span x-show="stop.status==='failed'">__warning__</span></span><span class="list-stop-text"><h3 x-text="stop.customer_name"></h3><span class="list-address" x-text="stop.address"></span><span class="list-metadata"><span class="list-distance" :aria-label="'Straight-line distance '+distanceLabel(stop)" :title="'Straight-line distance from your location'" x-text="distanceLabel(stop)"></span><span x-text="stop.time_window.replace('-','–')"></span><span class="status" :class="stop.status" x-text="label(stop.status)"></span><span x-show="isQueued(stop.reference)" class="waiting-label">Waiting to sync</span></span></span>__arrow__</button></template><div x-show="!visibleCount" class="empty"><h3>No matching stops</h3><p>Try another status or search term.</p></div></div></section>
<section class="detail-overlay map-stop-card" x-cloak x-show="detailOpen" x-transition:enter="detail-enter" x-transition:enter-start="detail-start" x-transition:enter-end="detail-end" x-transition:leave="detail-leave" x-transition:leave-start="detail-end" x-transition:leave-end="detail-start" role="region" aria-label="Stop details"><div class="sheet-grip"></div><div class="stop-card-body"><header class="stop-card-top"><span class="status" :class="selected.status"><span class="card-dot"></span><span x-text="label(selected.status)">Pending</span></span><span class="mono" x-text="selected.reference">TV-300002</span><button x-ref="backButton" class="icon-button close-stop" @click="closeDetail()" :aria-label="detailFromList?'Back to stop list':'Close stop details'"><span x-show="detailFromList">__back__</span><span x-show="!detailFromList">__close__</span></button></header><div class="stop-customer" x-text="selected.customer_name">Silverline Supplies</div><h2 class="stop-street" x-text="street">215 Pitt St</h2><p class="stop-locality" x-text="locality">Newtown NSW</p><div class="stop-card-facts"><span>__clock__<strong x-text="selected.time_window?.replace('-','–')">08:00–10:00</strong></span><span :class="{'waiting-label':isQueued(selectedId)}" x-text="isQueued(selectedId)?(syncing?'Sending update':'Waiting to sync'):selected.syncedAt?'Synced':'No pending update'">No pending update</span></div><div class="map-final-result" x-cloak x-show="selected.status!=='pending'" :class="{failed:selected.status==='failed'}"><span x-show="selected.status==='completed'">__checkcircle__</span><span x-show="selected.status==='failed'">__warning__</span><div><h3 x-text="selected.status==='completed'?'Delivery completed':'Delivery failed'"></h3><p x-text="selected.status==='failed'?(selected.failureReason||'No reason provided in the source record.'):(selected.updatedAt?'Recorded at '+time(selected.updatedAt):'Imported delivery record')"></p></div></div><div x-cloak x-show="saveError" class="save-error" role="alert" x-text="saveError"></div><footer class="stop-card-actions"><div x-show="selected.status==='pending'"><button class="primary complete-delivery" @click="update('completed')">__check__Complete delivery</button><button class="secondary fail-delivery" x-ref="failTrigger" @click="openFailure()">Report a failed delivery __arrow__</button></div><button class="primary return-map" x-show="selected.status!=='pending'" @click="closeDetail()"><span x-text="detailFromList?'Back to stops':'Back to map'">Back to map</span>__arrow__</button></footer></div></section>
<span class="home-indicator map-home-indicator" aria-hidden="true"></span>
__FAILURE__
<div class="toast" :data-tone="toastType" :style="{bottom:!detailOpen&&!listOpen?toastBottom+'px':null}" role="status" aria-live="polite" aria-atomic="true" x-cloak x-show="toast && !failureOpen && (toastIsSync || (!detailOpen && !listOpen))" x-transition.opacity.duration.180ms><span class="toast-symbol" :class="{rotating:toastType==='progress'}"><span x-show="toastType==='success'">__checkcircle__</span><span x-show="toastType==='progress'">__sync__</span><span x-show="toastType==='info'">__offline__</span><span x-show="toastType==='error'">__warning__</span></span><span x-text="toast"></span></div>
</main></body></html>'''
    extra={
        'locate':'<svg aria-hidden="true" viewBox="0 0 24 24"><path fill="none" stroke="currentColor" stroke-width="1.7" d="M12 2v3m0 14v3M2 12h3m14 0h3"/><circle cx="12" cy="12" r="7" fill="none" stroke="currentColor" stroke-width="1.7"/><circle cx="12" cy="12" r="2.5"/></svg>',
        'mapFit':'<svg aria-hidden="true" viewBox="0 0 24 24"><path fill="none" stroke="currentColor" stroke-width="1.7" d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/><rect x="8" y="8" width="8" height="8" rx="1.5" fill="none" stroke="currentColor" stroke-width="1.7"/></svg>',
        'mapIcon':'<svg aria-hidden="true" viewBox="0 0 24 24"><path fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round" d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16"/></svg>'
    }
    for key,value in dict(icons,**extra).items():
        template=template.replace('__'+key+'__',value)
    for key,value in {'DATA':json.dumps(data),'CONFIG':json.dumps(config),'ICONS':json.dumps(icons),'FILTERS':filters,'FAILURE':failure}.items():
        template=template.replace('__'+key+'__',value)
    return template
